import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0005: Why the Core Engine Coordinates the Graph","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0005-why-core-coordinates-the-graph.md","filePath":"adr/ADR-0005-why-core-coordinates-the-graph.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0005-why-core-coordinates-the-graph.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0005-why-the-core-engine-coordinates-the-graph" tabindex="-1">ADR-0005: Why the Core Engine Coordinates the Graph <a class="header-anchor" href="#adr-0005-why-the-core-engine-coordinates-the-graph" aria-label="Permalink to “ADR-0005: Why the Core Engine Coordinates the Graph”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/recovery-engine.md §6, ADR-0004</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The graph is built — who drives it? If resources or plugins each judge &quot;is my dependency healthy&quot; and self-recover, concurrent execution inevitably produces two resources simultaneously repairing the same dependency, recovery-order races, and unknowing duplicate restarts.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Recovery orchestration belongs exclusively to the Core Engine: each tick probes in topological order; dependency health is re-checked before recovery execution (§3.6); one recovery mutex per resource (the same resource never runs two recovery tasks concurrently); when a dependency is unhealthy, upstream resources wait (Waiting + waiter dedup) and the dependency&#39;s recovery result is shared to all waiters; budgets/cooldowns/high-risk counters are centralized state.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Resource/plugin autonomous recovery</strong>: races and ordering errors; duplicated side effects; no global budget control.</li><li><strong>External orchestrator (systemd dependencies)</strong>: systemd only manages service start ordering — it does not understand health probes or verification semantics; it moves core logic out of the core.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: single source of truth; wait/wake/dedup semantics centralized in one testable place; per-resource mutex naturally debounces. Cons: the central component is complex (large state machine); requires high implementation quality — hence vertical integration tests and crash-recovery tests guard the recovery path.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>engine.rs drive/waiters/redrive/finish_* are the heaviest core paths — changes require tests.</li><li>Plugins provide capabilities (actions) only; they must not make recovery decisions themselves (ADR-0015 toolbox model).</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};